14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    // Once a committed word selected an external subcommand, every remaining
46	    // word belongs to that external program and is never completed here.
47	    let mut in_external = false;
48	    while let Some(arg) = raw_args.next(&mut cursor) {
49	        let current_state = next_state;
50	        next_state = ParseState::ValueDone;
51	        debug!(
52	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
53	            arg.to_value_os(),
54	        );
55	        if let ParseState::Opt(state) = &current_state {
56	            // A value terminator ends a multi-value option regardless of the
57	            // word's shape: unlike a flag-like word, it never starts a new
58	            // argument, and unlike any other word, it is never one of the
59	            // option's values. A flag-shaped terminator only wins over flag
60	            // parsing when the option accepts hyphen values, matching the
61	            // parser's precedence.
62	            let opt = state.opt;
63	            if is_value_terminator(opt, &arg)
64	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
65	            {
66	                if cursor == target_cursor {
67	                    // The cursor sits on the terminator itself. Complete as if
68	                    // it had already been submitted and an empty word followed,
69	                    // so ordinary completion resumes and the terminator is not
70	                    // offered as a candidate.
71	                    raw_args.insert(&target_cursor, [OsString::new()]);
72	                    let mut word_cursor = target_cursor;
73	                    let word = raw_args
74	                        .next(&mut word_cursor)
75	                        .expect("an empty word was just inserted");
76	                    return complete_arg(
77	                        &word,
78	                        current_cmd,
79	                        current_dir,
80	                        pos_index,
81	                        is_escaped,
82	                        ParseState::ValueDone,
83	                        &used_args,
84	                    );
85	                }
86	                next_state = ParseState::ValueDone;
87	                continue;
88	            }
89	        }
90	        if in_external {
91	            // A committed word already selected an external subcommand; this
92	            // word (and every later one) is an argument of that external
93	            // program. Its command line is unknown, so rather than falling
94	            // back to the current command's subcommands, options, or
95	            // positionals, completion succeeds with an empty set.
96	            if cursor == target_cursor {
97	                return Ok(Vec::new());
98	            }
99	            continue;
100	        }
101	
102	        if cursor == target_cursor {
103	            return complete_arg(
104	                &arg,
105	                current_cmd,
106	                current_dir,
107	                pos_index,
108	                is_escaped,
109	                current_state,
110	                &used_args,
111	            );
112	        }
113	
114	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
115	            if let Ok(value) = arg.to_value() {
116	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
117	                    current_cmd = next_cmd;
118	                    pos_index = 1;
119	                    used_args.clear();
120	                    continue;
121	                }
122	                // An unknown plain word, with no positional slot left to
123	                // fill, selects an external subcommand: the parser routes
124	                // everything after it to that external program. Flag-like
125	                // words and the escape are still parsed as flags, matching
126	                // that precedence, and an empty word is a cursor placeholder
127	                // rather than a program name.
128	                if current_cmd.is_allow_external_subcommands_set()
129	                    && !arg.is_empty()
130	                    && !arg.is_escape()
131	                    && arg.to_long().is_none()
132	                    && arg.to_short().is_none()
133	                    && find_positional(current_cmd, pos_index, false).is_none()
134	                {
135	                    in_external = true;
136	                    continue;
137	                }
138	            }
139	        }
140	
141	        // A strict delimited group whose previous word opened another fragment
142	        // (a trailing delimiter) or went invalid owns the next word outright: a
143	        // flag, the `--` escape, or a subcommand name is then another value of
144	        // the group, never a scope switch. A continuation word that fills the
145	        // group closes it; otherwise the group stays pending for its remaining
146	        // fragments.
147	        if let ParseState::Opt(state) = &current_state {
148	            if state.is_strict_group() && (state.open || state.invalid) {
149	                let mut state = state.clone();
150	                state.observe(arg.to_value_os(), false);
151	                next_state =
152	                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
153	                        ParseState::ValueDone
154	                    } else {
155	                        ParseState::Opt(state)
156	                    };
157	                continue;
158	            }
159	        }
160	
161	        if is_escaped {
162	            (next_state, pos_index) =
163	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
164	        } else if arg.is_escape() {
165	            is_escaped = true;
166	            // Like the parser, `--` jumps straight to a `last(true)`
167	            // positional, skipping any unfilled positionals.
168	            if let Some(last_index) = current_cmd
169	                .get_positionals()
170	                .filter(|p| p.is_last_set())
171	                .filter_map(|p| p.get_index())
172	                .max()
173	            {
174	                pos_index = last_index;
175	            }
176	        } else if opt_allows_hyphen(&current_state, &arg) {
177	            match current_state {
178	                ParseState::Opt(mut state) => {
179	                    state.observe(arg.to_value_os(), false);
180	                    next_state = state.finish();
181	                }
182	                _ => unreachable!("else branch is only reachable in Opt state"),
183	            }
184	        } else if let Some((flag, value)) = arg.to_long() {
185	            if let Ok(flag) = flag {
186	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
187	
188	                if let Some(opt) = opt {
189	                    record_used_arg(&mut used_args, opt.get_id());
190	                    if opt.get_num_args().expect("built").takes_values() {
191	                        // An attached value (`--opt=value`) counts toward the
192	                        // option's values just like a space-separated one, so
193	                        // that completing after `--opt=value` sees the same
194	                        // state as completing after `--opt value`.
195	                        // An empty attached value (`--opt=`) types no value
196	                        // yet, so the option stays pending.
197	                        let mut state = OptState::new(opt);
198	                        if let Some(value) = value.filter(|v| !v.is_empty()) {
199	                            state.observe(value, true);
200	                        }
201	                        next_state = state.finish();
202	                    };
203	                } else if pos_allows_hyphen(current_cmd, pos_index) {
204	                    (next_state, pos_index) =
205	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
206	                }
207	            }
208	        } else if let Some(short) = arg.to_short() {
209	            let (_, matched_opts, takes_value_opt, mut short) =
210	                parse_shortflags(current_cmd, short);
211	            for opt in &matched_opts {
212	                record_used_arg(&mut used_args, opt.get_id());
213	            }
214	            if let Some(opt) = takes_value_opt {
215	                // An attached value (`-ovalue`, `-o=value`) counts toward the
216	                // option's values just like a space-separated one. An empty
217	                // attached value (`-o=`) types no value yet, so the option
218	                // stays pending instead of being treated as satisfied.
219	                let mut state = OptState::new(opt);
220	                if let Some(value) = short
221	                    .next_value_os()
222	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
223	                    .filter(|v| !v.is_empty())
224	                {
225	                    state.observe(value, true);
226	                }
227	                next_state = state.finish();
228	            } else if pos_allows_hyphen(current_cmd, pos_index) {
229	                (next_state, pos_index) =
230	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
231	            }
232	        } else {
233	            match current_state {
234	                ParseState::ValueDone | ParseState::Pos(..) => {
235	                    (next_state, pos_index) =
236	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
237	                }
238	                ParseState::Opt(mut state) => {
239	                    state.observe(arg.to_value_os(), false);
240	                    next_state = state.finish();
241	                }
242	            }
243	        }
244	    }
245	
246	    Err(std::io::Error::other("no completion generated"))
247	}
