1033	/// Whether the argument can be addressed by the long flag `flag`,
1034	/// including visible and hidden aliases.
1035	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
1036	    arg.get_long() == Some(flag)
1037	        || arg
1038	            .get_all_aliases()
1039	            .is_some_and(|aliases| aliases.contains(&flag))
1040	}
