1051	/// Remove argument candidates that are unavailable given the arguments
1052	/// already present on the command line.
1053	///
1054	/// Two rules apply:
1055	/// - Non-multiple argument groups: once any member of such a group is on the
1056	///   command line, every member of that group (including the selected one and
1057	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
1058	/// - Explicit conflicts: a candidate that conflicts with an already-used
1059	///   argument is removed; conflicts only need to be declared on one side.
1060	///
1061	/// Anything that is not an argument candidate (positional values,
1062	/// subcommands, custom candidates) is left untouched.
1063	fn filter_unavailable_args(
1064	    completions: &mut Vec<CompletionCandidate>,
1065	    cmd: &clap::Command,
1066	    used_args: &[clap::Id],
1067	) {
1068	    if used_args.is_empty() {
1069	        return;
1070	    }
1071	
1072	    // Members of non-multiple groups that already have a member present.
1073	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
1074	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
1075	        let members: Vec<&clap::Id> = group.get_args().collect();
1076	        if members
1077	            .iter()
1078	            .any(|id| used_args.iter().any(|used| used == *id))
1079	        {
1080	            excluded_by_group.extend(members.into_iter().cloned());
1081	        }
1082	    }
1083	
1084	    completions.retain(|candidate| {
1085	        let Some(arg) = candidate
1086	            .get_id()
1087	            .and_then(|id| id.strip_prefix("arg::"))
1088	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
1089	        else {
1090	            return true;
1091	        };
1092	        if excluded_by_group.contains(arg.get_id()) {
1093	            return false;
1094	        }
1095	        !used_args.iter().any(|used_id| {
1096	            cmd.get_arguments()
1097	                .find(|a| a.get_id() == used_id)
1098	                .is_some_and(|used| args_conflict(cmd, arg, used))
1099	        })
1100	    });
1101	}
