1103	/// Record an argument seen on the command line, keeping the first occurrence
1104	/// only so that repeating a flag neither alters filtering nor restores
1105	/// candidates already excluded.
1106	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
1107	    if !used_args.iter().any(|used| used == id) {
1108	        used_args.push(id.clone());
1109	    }
1110	}
