1175	/// Parse the positional arguments. Return the new state and the new positional index.
1176	fn parse_positional<'a>(
1177	    cmd: &clap::Command,
1178	    pos_index: usize,
1179	    is_escaped: bool,
1180	    state: ParseState<'a>,
1181	) -> (ParseState<'a>, usize) {
1182	    let pos_arg = cmd
1183	        .get_positionals()
1184	        .find(|p| p.get_index() == Some(pos_index));
1185	    let num_args = pos_arg
1186	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1187	        .unwrap_or(1);
1188	
1189	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1190	        if num_args > 1 {
1191	            (ParseState::Pos((pos_index, 1)), pos_index)
1192	        } else {
1193	            if is_escaped {
1194	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1195	            } else {
1196	                (ParseState::ValueDone, pos_index + 1)
1197	            }
1198	        }
1199	    };
1200	    match state {
1201	        ParseState::ValueDone => {
1202	            update_state_with_new_positional(pos_index)
1203	        },
1204	        ParseState::Pos((prev_pos_index, num_arg)) => {
1205	            if prev_pos_index == pos_index {
1206	                if num_arg + 1 < num_args {
1207	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1208	                } else {
1209	                    if is_escaped {
1210	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1211	                    } else {
1212	                        (ParseState::ValueDone, pos_index + 1)
1213	                    }
1214	                }
1215	            } else {
1216	                update_state_with_new_positional(pos_index)
1217	            }
1218	        }
1219	        ParseState::Opt(..) => unreachable!(
1220	            "This branch won't be hit,
1221	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1222	        ),
1223	    }
1224	}
1225	
1226	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1227	    cmd.get_positionals()
1228	        .find(|a| a.get_index() == Some(pos_index))
1229	        .map(|p| p.is_allow_hyphen_values_set())
1230	        .unwrap_or(false)
1231	}
1232	
1233	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
1234	/// for, honoring the value delimiter.
1235	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
1236	    match (opt.get_value_delimiter(), value.to_str()) {
1237	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
1238	        _ => 1,
1239	    }
1240	}
1241	
1242	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1243	    let val = arg.to_value_os();
1244	    if val.starts_with("-") {
1245	        if let ParseState::Opt(state) = state {
1246	            return state.opt.is_allow_hyphen_values_set();
1247	        }
1248	    }
1249	
1250	    false
1251	}
1252	
1253	/// Whether `arg` is the standalone value terminator of a pending option.
1254	///
1255	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
1256	/// word must consist of the terminator alone.
1257	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1258	    opt.get_value_terminator()
1259	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
1260	}
1261	
1262	/// Whether the parser would route this word through flag/escape parsing before
1263	/// a pending option gets to consume it as a value.
1264	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
1265	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
1266	}
1267	
1268	/// Whether a word can terminate a still-open multi-value option and start a
1269	/// new argument instead, the way the parser would read it.
1270	///
1271	/// While an option still owes values, the parser greedily consumes every plain
1272	/// word as one of its values; only flag-like words can switch to another
1273	/// argument. An option that accepts hyphen values consumes those too.
1274	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1275	    if arg.is_escape() {
1276	        // `--` cancels every pending option unless its values may start with `--`.
1277	        return !pending.is_allow_hyphen_values_set();
1278	    }
1279	    if !arg.to_value_os().starts_with("-") {
1280	        // A plain word is always another value of the pending option.
1281	        return false;
1282	    }
1283	    if pending.is_allow_hyphen_values_set() {
1284	        return false;
1285	    }
1286	    // `-` is a stdio/value, not a flag.
1287	    if arg.is_stdio() {
1288	        return false;
1289	    }
1290	    // Both long and short flag styles can start a new argument; unknown flags
1291	    // still switch (and error during parsing) rather than become option values.
1292	    arg.to_long().is_some() || arg.to_short().is_some()
1293	}
