                // A name that is not valid UTF-8 has no file stem; mirror the
                // parser, which leaves such a word for ordinary parsing.
                None => {}
            }
        }
    }

    // The words are addressed in their final order (`argv[0]` keeps index 0 and
    // an inserted applet shifts nothing before it). A cursor past every word
    // names no word to complete.
    let effective_len = args_len + usize::from(applet_inserted);
    if arg_index >= effective_len {
