#![cfg(feature = "unstable-dynamic")]

use std::ffi::OsString;

use clap::Command;

fn mc_cmd() -> Command {
    Command::new("busybox")
        .multicall(true)
        .subcommand(
            Command::new("busybox").subcommand(Command::new("status")).subcommand(Command::new("stop")),
        )
        .subcommand(
            Command::new("status")
                .arg(clap::Arg::new("format").long("format").value_parser(["text", "json"])),
        )
}

fn run(args: &[&str], index: Option<usize>) -> Vec<String> {
    let mut cmd = mc_cmd();
    let args: Vec<OsString> = args.iter().map(OsString::from).collect();
    let index = index.unwrap_or(args.len() - 1);
    clap_complete::engine::complete(&mut cmd, args, index, None)
        .unwrap()
        .into_iter()
        .map(|c| {
            format!(
                "{} [id={:?}] [tag={:?}] [help={:?}] [hide={}]",
                c.get_value().to_string_lossy(),
                c.get_id(),
                c.get_tag().map(|t| t.to_string()),
                c.get_help().map(|h| h.to_string()),
                c.is_hide_set()
            )
        })
        .collect()
}

#[test]
fn scratch_busybox_empty() {
    println!("{:#?}", run(&["/usr/bin/busybox", ""], None));
}

