    // hidden markers must agree between the two entry points.
    let inputs: &[&[&str]] = &[
        &["busybox", "status", ""],
        &["status", ""],
        &["busybox", "status", "--format", ""],
        &["status", "--format", ""],
        &["busybox", "status", "--format="],
        &["status", "--format="],
        &["busybox", "status", "--"],
